-- One-off import of the Discord export into the tracker's own tables.
-- Creates a single 'imported' run and one price_points row per alert.
WITH r AS (
  INSERT INTO public.runs (started_at, finished_at, status, error_summary)
  VALUES (now(), now(), 'imported', 'Backfilled from Discord export')
  RETURNING run_id
)
INSERT INTO public.price_points
  (run_id, observed_at, sail_date, ship_name, cabin_label, item_kind, current_price, paid_price,
   currency, discount_applied, status, rebook_decision, notified)
SELECT r.run_id, v.observed_at::timestamptz, v.sail_date, v.ship_name, v.cabin_label, 'cabin_fare',
       v.current_price::numeric, v.paid_price::numeric, v.currency, v.discount, 'priced',
       'consider_booking', 1
FROM r, (VALUES
